import json,os,pathlib,resource,signal,subprocess,sys,time
out=pathlib.Path(sys.argv[1]);command=sys.argv[2:]
start=time.monotonic(); process=subprocess.Popen(command,start_new_session=True)
peak_kb=0;peak_processes=0;limit_kb=10*1024*1024;limited=False
while True:
    stats={}
    for p in pathlib.Path('/proc').iterdir():
        if not p.name.isdecimal(): continue
        try:
            fields=(p/'stat').read_text().rsplit(')',1)[1].split()
            stats[int(p.name)]=(int(fields[1]),int(fields[21])*os.sysconf('SC_PAGE_SIZE')//1024)
        except (OSError,ValueError,IndexError): pass
    descendants={process.pid}
    while True:
        new={p for p,(parent,rss) in stats.items() if parent in descendants}-descendants
        if not new: break
        descendants.update(new)
    total=sum(stats[p][1] for p in descendants if p in stats)
    peak_kb=max(peak_kb,total);peak_processes=max(peak_processes,len(descendants))
    if total>limit_kb:
        limited=True;os.killpg(process.pid,signal.SIGTERM)
    status=process.poll()
    if status is not None: break
    if time.monotonic()-start>1200:
        limited=True;os.killpg(process.pid,signal.SIGTERM)
    time.sleep(.2)
result={'argv':command,'exit_code':status,'elapsed_seconds':time.monotonic()-start,'sampled_aggregate_peak_rss_kb':peak_kb,'peak_process_count':peak_processes,'child_max_rss_kb':resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss,'limit_exceeded':limited,'rss_sampling_seconds':.2}
out.write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result),flush=True)
sys.exit(status if status>=0 else 128-status)
